using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json.Linq;
public static class SpatialFix {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Vector3 V(JToken j)=>new Vector3((float)j[0],(float)j[1],(float)j[2]);
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying)throw new Exception("Edit required");if(s.isDirty)EditorSceneManager.SaveScene(s,Path.Combine(Path.GetTempPath(),"SpatialFix_recovery.unity"),true);var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("B5_Spatial_Refinement");
 foreach(string f in Directory.GetFiles(Application.dataPath+"/Afrer_Seconds/05.Model/Environment/B5","SF_*_Interior.fbx"))AssetDatabase.ImportAsset("Assets"+f.Substring(Application.dataPath.Length),ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);
 var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/plan.json"));foreach(var p in plan["placements"]){var t=group.Find((string)p["room"]+"/"+(string)p["id"]);t.localPosition=V(p["position"]);t.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);}
 var c02=group.Find("C02");foreach(var spec in new[]{new[]{5f,4.3f,4.3f,270f},new[]{6f,4.7f,3.05f,270f},new[]{7f,4.7f,1.8f,270f}}){var t=c02.Find("C02_Detail_"+(int)spec[0]);t.localPosition=new Vector3(spec[1],0,spec[2]);t.localRotation=Quaternion.Euler(0,spec[3],0);}
 int added=0;var infill=root.Find("C02_Security_Art/C02_Equipment_Infill");foreach(var t in infill.Cast<Transform>().ToArray()){string source=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject);if(!source.Contains("/Props/")||!t.gameObject.activeSelf)continue;string path="Assets/Afrer_Seconds/05.Model/Props/B5/SF_"+Path.GetFileName(source);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!prefab)continue;var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,c02);g.name="C02_"+prefab.name;g.transform.SetPositionAndRotation(t.position,t.rotation);var b=g.GetComponentInChildren<MeshFilter>().sharedMesh.bounds;var c=g.AddComponent<BoxCollider>();c.center=b.center;c.size=b.size;t.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);added++;}
 // AABB colliders incorrectly fill the gap around pipes and open video-wall feet.
 foreach(var t in group.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("PlateHeatExchanger")||t.name.Contains("TwinCoolingPump")||t.name=="C02_Detail_0")){var box=t.GetComponent<BoxCollider>();if(box)UnityEngine.Object.DestroyImmediate(box);foreach(var mf in t.GetComponents<MeshFilter>()){var mc=t.GetComponent<MeshCollider>();if(!mc)mc=t.gameObject.AddComponent<MeshCollider>();mc.sharedMesh=mf.sharedMesh;}}
 var av=c02.Find("C02_SF_SR_AVServiceRack");if(av){av.localPosition=new Vector3(-4.8f,0,3.8f);av.localRotation=Quaternion.Euler(0,90,0);}var fs=JArray.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_SpatialRefinement/fixtures.json"));int i=0;foreach(var f in fs){var t=group.Find((string)f["room"]+"/Fixture_Downlight_"+i++);t.localPosition=V(f["position"]);}
 foreach(var t in group.GetComponentsInChildren<Transform>(true)){if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var r in t.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(r);}foreach(var c in t.GetComponents<MeshCollider>())c.sharedMesh=t.GetComponent<MeshFilter>().sharedMesh;}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{added};}
}
